document.addEventListener('click',async e=>{if(!e.target.closest('#friends-alert'))return;let items=S.notifications||[],body=items.map(n=>`<div class="notification-item"><b>${esc(n.title)}</b>${n.type==='friend_incoming'?`<div><button class="primary" data-friend-request="accept" data-id="${n.request_id}">Принять</button> <button class="secondary" data-friend-request="reject" data-id="${n.request_id}">Отклонить</button></div>`:''}</div>`).join('')||'<div class="empty">Новых уведомлений нет</div>';await uiDialog('Уведомления',body,'Закрыть')});
